changeSet.sql:
DO $grants$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'smartmentor_api') THEN
        GRANT SELECT, INSERT, UPDATE, DELETE ON course_materials TO smartmentor_api;
        GRANT USAGE, SELECT ON SEQUENCE course_materials_id_seq TO smartmentor_api;
    ELSE
        RAISE NOTICE 'Role smartmentor_api does not exist: grants skipped';
    END IF;
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'smartmentor_ai') THEN
        GRANT SELECT ON course_materials TO smartmentor_ai;
    ELSE
        RAISE NOTICE 'Role smartmentor_ai does not exist: grant skipped';
    END IF;
END
$grants$;

rollback.sql:
DO $revoke$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'smartmentor_api') THEN
        REVOKE ALL ON course_materials FROM smartmentor_api;
        REVOKE ALL ON SEQUENCE course_materials_id_seq FROM smartmentor_api;
    END IF;
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'smartmentor_ai') THEN
        REVOKE ALL ON course_materials FROM smartmentor_ai;
    END IF;
END
$revoke$;
